use FACTURACION 

CREATE TABLE PROVINCIA (ID_PROVINCIA INT NOT NULL, PRO_NOMBRE VARCHAR(20) PRIMARY KEY NOT NULL, ID_PAIS INT NOT NULL)
CREATE TABLE SUBCATEGORIA (SUB_CODIGO INT PRIMARY KEY NOT NULL, SUB_DESCRIPCION VARCHAR(50) NULL)
CREATE TABLE SUPLIDORES (SUP_CODIGO INT NOT NULL, SUP_NOMBRE VARCHAR(50)PRIMARY KEY NOT NULL, SUP_FECHA DATE NOT NULL, SUP_DIRECCION VARCHAR(30) NULL, SUP_TELEFONO VARCHAR(12) NULL, SUP_EXTENSION INT NULL, SUP_CELULAR VARCHAR(12) NULL,
SUP_CONTACTO VARCHAR(30) NULL, SUP_CORREO VARCHAR(65)NULL, SUP_TipoNegocio varchar(8) null, SUP_STATUS BIT NULL, SUP_EMPRESA VARCHAR(18) NULL, SUP_PAGINA VARCHAR(29)NULL, SUP_PAIS VARCHAR(30) NULL, SUP_PROVINCIA VARCHAR(30) NULL,SUP_POSTAL INT NULL,
SUP_RNCEDULA INT NULL, SUP_REGISTRO VARCHAR(30) NULL, SUP_CREDITO DECIMAL(18,2) NULL, SUP_DESCUENTO DECIMAL(18,2) null, SUP_TERMINO VARCHAR(30) NULL, SUP_IMPUESTO BIT NULL, SUP_RETENCION BIT NULL, SUP_NOTA VARCHAR(100) NULL)
